function fixtureValue<T>(values: readonly T[], index: number): T {
  const value = values[index];
  if (value === undefined) throw new Error("Summer 2026 safe fixture contains an invalid lookup index.");
  return value;
}

function fixtureEquipment(): SafeScheduleEquipment[] {
  const names = new Set<string>();
  compactFixture.equipmentSets.forEach((equipmentSet) => equipmentSet.forEach((name) => names.add(name)));
  // The source has no unit-capacity field, so no capacity is inferred here.
  return [...names]
    .sort((first, second) => first.localeCompare(second))
    .map((name, displayOrder) => ({ name, displayOrder, isSingleUnit: false }));
}

function fixtureTimeBlocks(): SafeScheduleTimeBlock[] {
  return compactFixture.records.map((record, index) => {
    const [
      groupIndex,
      dayIndex,
      weekIndex,
      startMinute,
      endMinute,
      labelIndex,
      equipmentSetIndex,
      activityTypeIndex,
      confidenceIndex,
      reviewStatusIndex,
    ] = record;
    const eventLabel = fixtureValue(compactFixture.labels, labelIndex);
    return {
      // Generated locally instead of carrying a vault booking identifier.
      bookingId: `summer-2026-safe-${String(index + 1).padStart(4, "0")}`,
      day: fixtureValue(DAYS, dayIndex),
      week: fixtureValue(WEEKS, weekIndex),
      group: fixtureValue(compactFixture.groups, groupIndex),
      startMinute,
      endMinute,
      canonicalEventLabel: eventLabel,
      eventLabel,
      equipment: [...fixtureValue(compactFixture.equipmentSets, equipmentSetIndex)],
      activityType: fixtureValue(ACTIVITY_TYPES, activityTypeIndex),
      confidence: fixtureValue(CONFIDENCE, confidenceIndex),
      reviewStatus: fixtureValue(REVIEW_STATUS, reviewStatusIndex),
    };
  });
}

